#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define BUF_SIZE 1024

typedef struct {
    char *data;
    size_t len;
    pthread_mutex_t lock;
} Buffer;

Buffer *global_buf;

void *reader_thread(void *arg) {
    Buffer *buf = (Buffer *)arg;
    char local[BUF_SIZE];

    pthread_mutex_lock(&buf->lock);
    if (buf->data != NULL) {
        memcpy(local, buf->data, buf->len);
        printf("Read %zu bytes\n", buf->len);
    }
    pthread_mutex_unlock(&buf->lock);
    return NULL;
}

void *writer_thread(void *arg) {
    Buffer *buf = (Buffer *)arg;

    pthread_mutex_lock(&buf->lock);
    if (buf->data) {
        free(buf->data);
        buf->data = NULL;
        buf->len = 0;
    }
    pthread_mutex_unlock(&buf->lock);
    return NULL;
}

int main() {
    pthread_t t1, t2;

    global_buf = (Buffer *)malloc(sizeof(Buffer));
    if (!global_buf) return 1;

    global_buf->data = (char *)malloc(BUF_SIZE);
    if (!global_buf->data) { free(global_buf); return 1; }
    memset(global_buf->data, 'A', BUF_SIZE);
    global_buf->len = BUF_SIZE;
    pthread_mutex_init(&global_buf->lock, NULL);

    pthread_create(&t1, NULL, reader_thread, global_buf);
    pthread_create(&t2, NULL, writer_thread, global_buf);

    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    pthread_mutex_destroy(&global_buf->lock);
    free(global_buf);
    return 0;
}

#include <iostream>
#include <thread>
#include <mutex>
#include <vector>

class Buffer {
public:
    Buffer(size_t size) : data_(new char[size]), size_(size), mutex_() {}
    ~Buffer() {
        std::lock_guard<std::mutex> lock(mutex_);
        delete[] data_;
    }

    void resize(size_t new_size) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (new_size == 0) {
            delete[] data_;
            data_ = nullptr;
            size_ = 0;
            return;
        }
        char* new_data = new char[new_size];
        std::copy(data_, data_ + std::min(size_, new_size), new_data);
        delete[] data_;
        data_ = new_data;
        size_ = new_size;
    }

    void write(char c) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (data_ == nullptr) {
            std::cout << "Buffer is null\n";
            return;
        }
        data_[0] = c;
    }

private:
    char* data_;
    size_t size_;
    std::mutex mutex_;
};

void thread_func(Buffer& buf) {
    for (int i = 0; i < 100; ++i) {
        buf.resize(128);
        buf.write('x');
    }
}

int main() {
    Buffer buf(64);
    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) {
        threads.emplace_back(thread_func, std::ref(buf));
    }
    for (auto& t : threads) {
        t.join();
    }
    return 0;
}

