// 计算文件大小（存在整数溢出风险）
uint32_t getFileSize(const std::string& path) {
    std::ifstream file(path, std::ios::binary | std::ios::ate);
    if (!file.is_open()) {
        return 0;
    }
    std::streamoff size = file.tellg();
    file.close();
    // 漏洞点：streamoff 可能为 64 位，强制转换为 uint32_t 导致截断
    return static_cast<uint32_t>(size);
}

bool copyFileChunk(const std::string& src, const std::string& dst, uint32_t offset, uint32_t length) {
    std::ifstream in(src, std::ios::binary);
    std::ofstream out(dst, std::ios::binary | std::ios::app);
    if (!in.is_open() || !out.is_open()) {
        return false;
    }

    in.seekg(offset, std::ios::beg);
    if (!in.good()) {
        return false;
    }

    // 分配缓冲区（长度由外部传入，可能被截断后的值控制）
    std::vector<char> buffer(length);
    if (buffer.size() != length) {  // 防御：检查实际分配大小
        return false;
    }

    in.read(buffer.data(), length);
    std::streamsize bytesRead = in.gcount();
    if (bytesRead > 0) {
        out.write(buffer.data(), bytesRead);
    }
    return true;
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        std::cerr << "Usage: " << argv[0] << " <src> <dst> <offset> <length>\n";
        return 1;
    }

    std::string src = argv[1];
    std::string dst = argv[2];
    uint32_t offset = static_cast<uint32_t>(std::stoull(argv[3]));
    uint32_t length = static_cast<uint32_t>(std::stoull(argv[4]));

    // 漏洞触发路径：length 被截断为小值，但 offset 可能指向文件末尾
    if (!copyFileChunk(src, dst, offset, length)) {
        std::cerr << "Copy failed\n";
        return 1;
    }

    // 另一个漏洞点：getFileSize 返回截断值，用于后续比较
    uint32_t fileSize = getFileSize(src);
    if (offset + length > fileSize) {
        std::cerr << "Warning: read beyond file size\n";
    }

    std::cout << "Copy completed\n";
    return 0;
}

