// Config 模拟从配置文件加载的监控目标列表
type Config struct {
	AllowedHosts []string `json:"allowed_hosts"` // 可信的 API 域名白名单
}

var globalConfig Config

func loadConfig(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return json.Unmarshal(data, &globalConfig)
}

// fetchMetrics 从指定的 API 端点拉取指标，用于定时上报
func fetchMetrics(rawURL string) ([]byte, error) {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid url: %w", err)
	}

	// 白名单校验：只允许访问配置中列出的主机
	host := parsed.Hostname()
	allowed := false
	for _, h := range globalConfig.AllowedHosts {
		if h == host {
			allowed = true
			break
		}
	}
	if !allowed {
		return nil, fmt.Errorf("host %q not in allowed list", host)
	}

	// 仅允许 http/https 协议，防止 file:// 等非预期协议
	if parsed.Scheme != "http" && parsed.Scheme != "https" {
		return nil, fmt.Errorf("scheme %q not allowed", parsed.Scheme)
	}

	// 发起 HTTP 请求（此处模拟，真实场景会使用 http.Client）
	resp, err := http.Get(parsed.String())
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	return io.ReadAll(resp.Body)
}

// scheduledJob 定时任务入口：每 30 秒拉取一次指标
func scheduledJob() {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		// 模拟从环境变量或配置中心动态获取目标地址（攻击者可控）
		target := os.Getenv("METRICS_API_URL")
		if target == "" {
			continue
		}
		data, err := fetchMetrics(target)
		if err != nil {
			fmt.Printf("fetch failed: %v\n", err)
			continue
		}
		fmt.Printf("metrics fetched: %d bytes\n", len(data))
	}
}

func main() {
	if err := loadConfig("/etc/metrics/config.json"); err != nil {
		panic(err)
	}
	go scheduledJob()
	select {}
}

// 密码重置功能 - 基于 Spring Boot 的 REST 控制器
const express = require('express');
const crypto = require('crypto');
const router = express.Router();

// 模拟用户数据库
const users = [
  { id: 1, email: 'admin@example.com', passwordHash: 'hash1', resetToken: null, resetExpiry: null },
  { id: 2, email: 'user@example.com', passwordHash: 'hash2', resetToken: null, resetExpiry: null }
];

// 辅助函数：生成随机令牌
function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

// 1. 发起密码重置请求
router.post('/api/reset-password/request', (req, res) => {
  const { email } = req.body;
  const user = users.find(u => u.email === email);

  if (!user) {
    // 统一响应，防止用户枚举
    return res.status(200).json({ message: '如果该邮箱存在，重置链接已发送' });
  }

  const token = generateToken();
  user.resetToken = token;
  user.resetExpiry = Date.now() + 3600000; // 1小时有效

  // 模拟发送邮件（实际会通过邮件服务）
  console.log(`重置链接: /reset-password?token=${token}`);
  res.status(200).json({ message: '如果该邮箱存在，重置链接已发送' });
});

// 2. 校验令牌有效性（用于前端展示重置表单前）
router.get('/api/reset-password/validate', (req, res) => {
  const { token } = req.query;

  // 防御：检查令牌格式（仅十六进制）
  if (!token || !/^[a-f0-9]{64}$/.test(token)) {
    return res.status(400).json({ error: '无效的令牌格式' });
  }

  const user = users.find(u => u.resetToken === token);
  if (!user || user.resetExpiry < Date.now()) {
    return res.status(400).json({ error: '令牌无效或已过期' });
  }

  res.status(200).json({ valid: true });
});

// 3. 执行密码重置
router.post('/api/reset-password/confirm', (req, res) => {
  const { token, newPassword } = req.body;

  // 防御：检查令牌格式
  if (!token || !/^[a-f0-9]{64}$/.test(token)) {
    return res.status(400).json({ error: '无效的令牌格式' });
  }

  // 直接使用用户提供的令牌查询
  const user = users.find(u => u.resetToken === token);

  if (!user) {
    return res.status(400).json({ error: '令牌无效' });
  }

  // 检查过期
  if (user.resetExpiry < Date.now()) {
    return res.status(400).json({ error: '令牌已过期' });
  }

  // 更新密码（实际会进行哈希处理）
  user.passwordHash = crypto.createHash('sha256').update(newPassword).digest('hex');
  user.resetToken = null;
  user.resetExpiry = null;

  res.status(200).json({ message: '密码已重置，请重新登录' });
});

module.exports = router;
